import java.util.*; import java.io.*; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line1 = br.readLine(); if (line1 == null) return; String[] parts = line1.split(" "); int startKey = Integer.parseInt(parts[0]); int targetKey = Integer.parseInt(parts[1]); int n = Integer.parseInt(br.readLine()); int[] keys = new int[n]; StringTokenizer st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { keys[i] = Integer.parseInt(st.nextToken()); } int[] dist = new int[100000]; Arrays.fill(dist, -1); Queue<Integer> queue = new LinkedList<>(); queue.add(startKey); dist[startKey] = 0; while (!queue.isEmpty()) { int curr = queue.poll(); if (curr == targetKey) { System.out.println(dist[curr]); return; } for (int k : keys) { int next = (int) (((long) curr * k) % 100000); if (dist[next] == -1) { dist[next] = dist[curr] + 1; queue.add(next); } } } System.out.println(-1); } }